'use client';
import Customers from './Customers';
import CustomerQuoteButton from './CustomerQuoteButton';
import Products from './Products';
import PlateEditor from './PlateEditor';
import {productQuote,resizeProductQuote,normalizeProduct} from '../../lib/products.mjs';
import InvestmentPanel from './InvestmentPanel';
import {useEffect,useState,useRef} from 'react';
import Account from './Account';
import Maintenance from './Maintenance';
import {equipmentHours,maintenanceStatus} from '../../lib/maintenance.mjs';
import CostAnalysis from './CostAnalysis';
import {calculate} from '../../lib/calculate.mjs';
import {filamentCatalog,matchCatalog} from '../../lib/catalog.mjs';
import {summarize} from '../../lib/finance.mjs';
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(n)||0);
const decimal=n=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2}).format(Number(n)||0);
const today=()=>new Date().toLocaleDateString('en-CA');
const initial={quantity:'',grams:'',kgPrice:'',hours:'',watts:'',kwh:'',machineValue:'',lifeHours:'',laborMinutes:'',hourRate:'',extras:'',failurePercent:'',feePercent:'',fixedFee:'',taxPercent:'',markupPercent:'',discountValue:'',discountType:'percent',materialId:'',equipmentId:''};
const empty={customers:[],products:[],materials:[],equipment:[],quotes:[],jobs:[],sales:[],entries:[],movements:[],maintenance_plans:[],maintenance_logs:[],equipment_hour_logs:[]};
const tabs=[['overview','Visão geral','◈'],['calculator','Precificação','⌘'],['quotes','Orçamentos','▤'],['products','Produtos','▧'],['customers','Clientes','♧'],['production','Produção','▦'],['stock','Estoque','◇'],['sales','Vendas','↗'],['equipment','Máquinas e ferramentas','⚙'],['maintenance','Manutenção','◷'],['finance','Financeiro','◎'],['account','Conta e acesso','◉']];
function Field({label,children,hint}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function Input({name,label,type='text',value,onChange,step='any',min=0,...props}){return <Field label={label}><input name={name} type={type} step={step} min={type==='number'?min:undefined} value={value} onChange={onChange} {...props}/></Field>}
function NumberField({label,name,values,set,hint}){return <Field label={label} hint={hint}><input type="number" min="0" step="any" value={values[name]} onChange={e=>set({...values,[name]:e.target.value})}/></Field>}
function Table({headers,rows,emptyText='Nenhum registro ainda.'}){return rows.length?<div className="table-scroll"><table><thead><tr>{headers.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.map((row,i)=><tr key={i}>{row.map((cell,j)=><td key={j}>{cell}</td>)}</tr>)}</tbody></table></div>:<div className="empty"><span>◇</span><strong>{emptyText}</strong><p>Os registros que você adicionar aparecerão aqui.</p></div>}
function Badge({children,tone=''}){return <span className={'badge '+tone}>{children}</span>}
function MaterialPhoto({material}){const [failed,setFailed]=useState(false);const catalog=matchCatalog(material);const url=material.image_url||catalog?.image_url;useEffect(()=>setFailed(false),[url]);return url&&!failed?<img className="material-photo" src={url} alt={[material.brand,material.material_type,material.color].filter(Boolean).join(' · ')||material.name} onError={()=>setFailed(true)}/>:<div className="material-photo no-photo"><span className="color-swatch" style={{background:material.color_hex||'#808080'}}/><small>{failed?'Foto indisponível':'Sem foto cadastrada'}</small></div>;}
export default function App({identity}){
 const dialogRef=useRef(null);
 const [maintenanceDay,setMaintenanceDay]=useState(today());
 useEffect(()=>{const timer=setInterval(()=>setMaintenanceDay(today()),60000);return()=>clearInterval(timer);},[]);
 const canWrite=identity.role==='owner'&&identity.company.status==='active';
 const [tab,setTab]=useState('overview'),[data,setData]=useState(empty),[loading,setLoading]=useState(true),[connected,setConnected]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false),[modal,setModal]=useState(null);
 const [step,setStep]=useState(0),[description,setDescription]=useState(''),[stockSearch,setStockSearch]=useState(''),[stockBrand,setStockBrand]=useState(''),[stockType,setStockType]=useState(''),[brandChoice,setBrandChoice]=useState(''),[colorChoice,setColorChoice]=useState('');
 const [values,setValues]=useState(initial),[projectName,setProjectName]=useState(''),[customer,setCustomer]=useState(''),[customerId,setCustomerId]=useState(''),[editingQuote,setEditingQuote]=useState(null);
 const [from,setFrom]=useState(''),[to,setTo]=useState('');
 async function refresh(){setLoading(true);try{const r=await fetch('/api/data',{cache:'no-store'});const d=await r.json();if(r.status===401||r.status===403){setData(empty);setConnected(false);window.location.replace('/login');return;}if(!r.ok)throw new Error(d.error);setData(d);setConnected(true);setError('');}catch(e){setConnected(false);setError(e.message);}finally{setLoading(false);}}
 useEffect(()=>{refresh();},[]);
 useEffect(()=>{
  let checking=false,disposed=false;
  const hide=e=>{if(e.persisted)document.documentElement.style.visibility='hidden';};
  const restore=e=>{if(e.persisted)window.location.reload();};
  async function validate(){if(checking||document.visibilityState==='hidden')return;checking=true;try{const r=await fetch('/api/auth',{cache:'no-store'});if(disposed)return;if(r.status===401||r.status===403){setData(empty);setConnected(false);document.documentElement.style.visibility='hidden';window.location.replace('/login');return;}if(!r.ok)return;const account=await r.json();if(account.user.id!==identity.user.id||account.company.id!==identity.company.id||account.role!==identity.role||account.company.status!==identity.company.status)window.location.replace('/');}catch{}finally{checking=false;}}
  window.addEventListener('pagehide',hide);window.addEventListener('pageshow',restore);window.addEventListener('focus',validate);document.addEventListener('visibilitychange',validate);
  return()=>{disposed=true;window.removeEventListener('pagehide',hide);window.removeEventListener('pageshow',restore);window.removeEventListener('focus',validate);document.removeEventListener('visibilitychange',validate);};
 },[identity.user.id,identity.company.id,identity.role,identity.company.status]);
 useEffect(()=>{if(!modal)return;const before=document.activeElement;const box=dialogRef.current;const focusable=()=>Array.from(box.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),[tabindex="0"]'));focusable().find(el=>el.tagName!=='BUTTON')?.focus();function trap(e){if(e.key!=='Tab')return;const list=focusable();const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}box.addEventListener('keydown',trap);return()=>{box.removeEventListener('keydown',trap);before?.focus();};},[modal]);
 useEffect(()=>{function key(e){if(e.key==='Escape'&&!busy)setModal(null);}window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key);},[busy]);
 async function save(payload){if(!canWrite){setError('Sua conta tem acesso somente de leitura.');return false;}setBusy(true);setError('');setNotice('');try{const r=await fetch('/api/data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw new Error(d.error);setModal(null);await refresh();setNotice(payload.action==='deleteQuote'?'Orçamento excluído.':'Registro salvo.');return d;}catch(e){setError(e.message);return false;}finally{setBusy(false);}}
 async function submit(e){e.preventDefault();const form=new FormData(e.currentTarget);const v=Object.fromEntries(form);const file=form.get('imageFile');delete v.imageFile;if(file instanceof File&&file.size){setBusy(true);try{const upload=new FormData();upload.set('image',file);const response=await fetch('/api/images',{method:'POST',body:upload});const image=await response.json();if(!response.ok)throw new Error(image.error);v.imageUrl=image.imageUrl;}catch(e){setError(e.message);setBusy(false);return;}}if(modal.action==='finish'&&productionQuote?.input.materials)v.materials=productionQuote.input.materials.map(m=>({materialId:m.materialId,grams:v['grams_'+m.materialId]}));for(const key of ['paid','recordPayment','affectsResult'])v[key]=v[key]==='on';save({...modal.payload,...v,action:modal.action});}
 let result,calculationError;try{result=calculate(values);}catch(e){calculationError=values.quantity===''?'Selecione um produto ou informe a quantidade e os dados de impressão para calcular.':e.message;}
 const selectedMaterial=data.materials.find(m=>m.id===values.materialId);
 const filament=data.materials.filter(m=>m.unit==='g');
 const brands=[...new Set(filament.map(m=>m.brand).filter(Boolean))].sort();
 const colors=[...new Set(filament.filter(m=>!brandChoice||m.brand===brandChoice).map(m=>m.color).filter(Boolean))].sort();
 const variants=filament.filter(m=>(!brandChoice||m.brand===brandChoice)&&(!colorChoice||m.color===colorChoice));
 const chooseMaterial=m=>{setValues(v=>({...v,materialId:m?.id||'',kgPrice:m?(m.cost_pending?'':Number(m.unit_cost)*1000):v.kgPrice}));};
 const visibleMaterials=data.materials.filter(m=>(!stockBrand||m.brand===stockBrand)&&(!stockType||m.material_type===stockType)&&[m.name,m.sku,m.brand,m.color,m.material_type].join(' ').toLowerCase().includes(stockSearch.toLowerCase()));
 const materialDefaults=modal?.draft||(modal?.payload?.materialId?data.materials.find(m=>m.id===modal.payload.materialId):null);
 const steps=['Projeto','Material','Impressão','Custos','Taxas'];
 function newQuote(client){setValues({...initial});setProjectName('');setCustomer(client?.name||'');setCustomerId(client?.id||'');setDescription('');setEditingQuote(null);setBrandChoice('');setColorChoice('');setStep(0);setTab('calculator');setError('');setNotice('');}
 function loadQuote(q,edit=false){setValues({...initial,...q.input});setProjectName(q.name);setCustomer(q.customer||'');setCustomerId(q.customer_id||'');setDescription(q.description||'');setEditingQuote(edit?{id:q.id,version:q.version}:null);setBrandChoice('');setColorChoice('');setStep(0);setTab('calculator');setError('');}
 async function saveQuote(produce=false){const saved=await save({action:editingQuote?'quoteUpdate':'quote',quoteId:editingQuote?.id,version:editingQuote?.version,name:projectName,customer,customerId,description,input:values});if(saved){setEditingQuote({id:saved.id,version:editingQuote?editingQuote.version+1:0});if(produce)open('job','Produzir orçamento',{quoteId:saved.id});}}

 function useProduct(product){try{setValues(productQuote(product,1,data.materials,data.equipment));setProjectName(product.name);setDescription(product.description||'');setBrandChoice('');setColorChoice('');setStep(0);setTab('calculator');setError('');}catch(e){setError(e.message);}}
 function setQuantity(v){if(values.productId){try{setValues(resizeProductQuote(values,v.quantity));setError('');}catch(e){setError(e.message);}}else setValues(v);}
 const productionQuote=modal?.payload?.jobId?quoteOfJob(modal.payload.jobId):null;
 function quoteOfJob(jobId){return data.quotes.find(q=>q.id===data.jobs.find(j=>j.id===jobId)?.quote_id);}
 const maintenanceAlerts=(data.maintenance_plans||[]).flatMap(p=>{const e=data.equipment.find(e=>e.id===p.equipment_id);if(!e)return [];const status=maintenanceStatus(p,e,maintenanceDay);return ['overdue','due','soon'].includes(status.state)?[{...p,equipment:e,status}]:[];});
 const totals=summarize(data,from,to);
 const quoteOf=id=>data.quotes.find(q=>q.id===id);
 const nameOfJob=id=>{const job=data.jobs.find(j=>j.id===id);return quoteOf(job?.quote_id)?.name||'Produção';};
 const availableJobs=data.jobs.filter(j=>j.status==='concluido'&&!data.sales.some(s=>s.job_id===j.id));
 const lowStock=data.materials.filter(m=>Number(m.quantity)<=Number(m.minimum));
 const open=(action,title,payload={})=>setModal({action,title,payload});
 const addActions={stock:()=>open('material','Novo material'),equipment:()=>open('equipment','Cadastrar equipamento'),sales:()=>open('sale','Registrar venda'),finance:()=>open('entry','Novo lançamento'),production:()=>open('job','Nova produção'),quotes:()=>newQuote(),calculator:()=>newQuote()};
 function options(items,label){return <><option value="">Selecione</option>{items.map(i=><option value={i.id} key={i.id}>{label(i)}</option>)}</>}
 function download(){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),version:1,...data},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='moldae-'+today()+'.json';a.click();URL.revokeObjectURL(a.href);}
 return <div className="shell"><aside className="sidebar"><a className="brand" href="/" aria-label="Moldaê início"><span className="brand-icon">◇</span><span>Moldaê<small>GESTÃO DA PRODUÇÃO 3D</small></span></a><p className="nav-label">ÁREA DE TRABALHO</p><nav>{tabs.map(([key,label,icon])=><button key={key} className={tab===key?'active':''} onClick={()=>setTab(key)}><span aria-hidden="true">{icon}</span>{label}{key==='maintenance'&&maintenanceAlerts.length>0&&<i>{maintenanceAlerts.length}</i>}{key==='production'&&data.jobs.filter(j=>j.status==='fila').length>0&&<i>{data.jobs.filter(j=>j.status==='fila').length}</i>}</button>)}</nav><div className="sidebar-bottom"><span className={'connection '+(connected?'ok':'')}>{connected?'Banco conectado':'Banco desconectado'}</span><small>Gestão local • BRL</small><button className="secondary" onClick={download} disabled={!connected}>Exportar registros</button></div></aside>
 <main><header className="topbar"><span>Workspace <span className="slash">/</span> {tabs.find(t=>t[0]===tab)?.[1]}</span><button className="avatar" onClick={()=>refresh()} title="Atualizar dados" aria-label="Atualizar dados">↻</button></header><div className="content">
 {error&&<div role="alert" className="alert error">{error}<button onClick={()=>setError('')} aria-label="Fechar aviso">×</button></div>}{notice&&<div role="status" className="alert success">{notice}<button onClick={()=>setNotice('')} aria-label="Fechar aviso">×</button></div>}
 <div className="session-bar"><span>{identity.company.name} · {identity.user.name} · {canWrite?'Proprietário':'Somente leitura'}</span><button className="text-button" onClick={async()=>{const r=await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'logout'})});if(r.ok){setData(empty);document.documentElement.style.visibility='hidden';window.location.replace('/login');}}}>Sair da conta</button></div><div className="page-heading"><div><p className="eyebrow">{tab==='overview'?'CONTROLE PARA CRESCER':'MOLDAÊ'}</p><h1>{tabs.find(t=>t[0]===tab)?.[1]}</h1><p>{({overview:'Acompanhe o dinheiro, a produção e o resultado do seu trabalho.',calculator:'Entenda cada custo antes de definir o preço.',customers:'Cadastre contatos e acompanhe os pedidos de cada cliente.',products:'Configure o consumo de referência e reutilize nos orçamentos.',quotes:'Propostas salvas com os custos da data do orçamento.',production:'Registre o consumo real e acompanhe as impressões.',stock:'Filamentos e insumos, com histórico de movimentação.',sales:'Vendas do lote completo, recebimentos e resultado.',equipment:'Seu patrimônio e as horas de uso das impressoras.',maintenance:'Depreciação, cuidados programados e histórico das impressoras.',finance:'Entradas, saídas, investimentos e despesas.',account:'Empresa, usuários, segurança e plano.'})[tab]}</p></div>{addActions[tab]&&<button className="primary" onClick={addActions[tab]} disabled={!connected&&tab!=='quotes'}>＋ {({stock:'Material',equipment:'Equipamento',sales:'Venda',finance:'Lançamento',production:'Produção',quotes:'Orçamento',calculator:'Novo orçamento'})[tab]}</button>}</div>
 {['overview','finance'].includes(tab)&&<><div className="period"><span>Período</span><input aria-label="Data inicial" type="date" value={from} onChange={e=>setFrom(e.target.value)}/><span>até</span><input aria-label="Data final" type="date" value={to} onChange={e=>setTo(e.target.value)}/><button className="text-button" onClick={()=>{setFrom('');setTo('');}}>Todo o histórico</button></div><div className="stats"><div className="stat"><span>Faturamento</span><strong>{money(totals.revenue)}</strong><small>Vendas registradas no período</small></div><div className="stat accent"><span>Resultado gerencial</span><strong>{money(totals.profit)}</strong><small>Custos, taxas, perdas e despesas</small></div><div className="stat"><span>Movimentação líquida de caixa</span><strong>{money(totals.cash)}</strong><small>Entradas menos saídas no período</small></div><div className="stat"><span>Perdas na produção</span><strong className={totals.loss?'negative':''}>{money(totals.loss)}</strong><small>Custo das impressões com falha</small></div></div></>}
 {tab==='overview'&&<>{maintenanceAlerts.length>0&&<div className="maintenance-banner"><div><strong>{maintenanceAlerts.length} aviso(s) de manutenção</strong><p>{maintenanceAlerts.slice(0,3).map(p=>p.equipment.name+': '+p.title).join(' · ')}</p></div><button className="primary" onClick={()=>setTab('maintenance')}>Ver cuidados</button></div>}<div className="dashboard-grid"><section className="panel"><div className="panel-heading"><h2>Como está sua operação</h2><Badge>Agora</Badge></div><div className="operation"><div><strong>{data.jobs.filter(j=>j.status==='fila').length}</strong><span>Na fila de produção</span></div><div><strong>{availableJobs.length}</strong><span>Lotes prontos para venda</span></div><div><strong>{money(totals.receivable)}</strong><span>A receber · todo o histórico</span></div></div><button className="primary" onClick={()=>newQuote()}>Calcular uma nova peça <span>↗</span></button></section><section className="panel"><div className="panel-heading"><h2>Atenção ao estoque</h2><Badge tone={lowStock.length?'warn':''}>{lowStock.length} itens</Badge></div>{lowStock.length?lowStock.slice(0,5).map(m=><div className="list-row" key={m.id}><span>{m.name}</span><b>{decimal(m.quantity)} {m.unit}</b></div>):<p className="muted">{data.materials.length?'Todos os materiais estão acima do mínimo.':'Cadastre os materiais e registre a primeira compra.'}</p>}<button className="text-button" onClick={()=>setTab('stock')}>Ver estoque →</button></section></div><section className="panel"><div className="panel-heading"><h2>Últimos orçamentos</h2><button className="text-button" onClick={()=>setTab('quotes')}>Ver todos →</button></div><Table headers={['Projeto','Cliente','Quantidade','Preço do lote','Lucro previsto']} rows={data.quotes.slice(0,5).map(q=>[q.name,q.customer||'—',q.result.quantity,money(q.result.price),money(q.result.profit)])} emptyText="Sua primeira peça começa com um bom preço."/></section><p className="footnote">O resultado gerencial inclui energia, trabalho e amortização calculados na produção. O caixa considera somente os pagamentos registrados. Aportes não são vendas.</p></>}
 {tab==='customers'&&<Customers data={data} company={identity.company.name} canWrite={canWrite} busy={busy} onSave={save} onQuote={newQuote}/>}
 {tab==='products'&&<Products products={data.products||[]} materials={data.materials} equipment={data.equipment} defaults={{...initial,quantity:1,lifeHours:10000,machineValue:0,watts:0}} canWrite={canWrite} busy={busy} onSave={save} onUse={p=>{newQuote();useProduct(p);}}/>}
 {tab==='calculator'&&<div className="calculator-grid"><div className="calculator-fields"><nav className="stepper" aria-label="Etapas do orçamento">{steps.map((label,i)=><button key={label} className={step===i?'current':i<step?'done':''} aria-current={step===i?'step':undefined} onClick={()=>setStep(i)}><span>{i<step?'✓':i+1}</span><b>{label}</b></button>)}</nav><section className="panel wizard-panel"><div className="panel-heading"><h2>{step+1}. {['Informações do projeto','Materiais utilizados','Equipamento e impressão','Trabalho e custos adicionais','Taxas e impostos'][step]}</h2><Badge>{step+1} de 5</Badge></div>
 {step===0&&<>{editingQuote&&<p className="info-box">Editando orçamento salvo. As alterações atualizam este mesmo registro.</p>}<div className="form-grid"><Field label="Produto cadastrado (opcional)"><select value={values.productId||''} onChange={e=>{const p=(data.products||[]).find(p=>p.id===e.target.value);if(p)useProduct(p);else setValues({...values,productId:'',productName:''});}}><option value="">Orçamento avulso</option>{(data.products||[]).map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><NumberField label="Quantidade de produtos completos" name="quantity" values={values} set={setQuantity}/></div>{values.productId&&<div className="info-box">{values.quantity} unidade(s) · {decimal(values.grams)} g · {decimal(values.hours)} h no lote. Quantidade altera consumo, tempo, trabalho e extras proporcionalmente.</div>}<p className="step-intro">Identifique a peça e o cliente para organizar seus orçamentos.</p><div className="form-grid"><Field label="Cliente cadastrado"><select value={customerId} onChange={e=>{const c=data.customers.find(c=>c.id===e.target.value);setCustomerId(c?.id||'');setCustomer(c?.name||'');}}><option value="">Sem cadastro / informar nome</option>{data.customers.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Input label="Nome do cliente no orçamento" value={customer} readOnly={!!customerId} onChange={e=>setCustomer(e.target.value)} placeholder="Selecione acima ou digite"/><Input label="Nome do projeto" value={projectName} onChange={e=>setProjectName(e.target.value)} placeholder="Ex.: Suporte para headset"/><Field label="Descrição para o cliente (aparece no PDF)"><textarea rows="7" value={description} onChange={e=>setDescription(e.target.value)} placeholder="Descreva a peça, personalização, acabamento e observações do pedido."/></Field></div><div className="info-box">O orçamento salva uma cópia dos preços e custos usados nesta simulação.</div></>}
 {step===1&&values.plates?.length>0&&<><h3>Mesas para este lote</h3><PlateEditor plates={values.plates} materials={data.materials} onChange={plates=>{const next={...values,plates};try{setValues(normalizeProduct(next));setError('');}catch(e){setValues(next);setError(e.message);}}}/><p className="info-box">Os tempos e consumos abaixo já correspondem às {values.quantity} unidades do orçamento. Ajuste conforme o fatiador.</p></>}
 {step===1&&!values.plates?.length&&values.materials?.length>0&&<><h3>Filamentos do lote</h3>{values.materials.map((m,i)=><div className="form-grid" key={m.materialId}><Field label={data.materials.find(x=>x.id===m.materialId)?.name||m.name||'Filamento'}><input aria-label={'Consumo '+(m.name||'filamento')} type="number" min="0" step="any" value={m.grams} onChange={e=>{const list=values.materials.map((x,j)=>j===i?{...x,grams:e.target.value}:x);setValues({...values,materials:list,grams:list.reduce((sum,x)=>sum+Number(x.grams),0)});}}/></Field><Field label="Preço por kg (R$)"><input type="number" min="0" step="any" value={m.kgPrice} onChange={e=>setValues({...values,materials:values.materials.map((x,j)=>j===i?{...x,kgPrice:e.target.value}:x)})}/></Field></div>)}<NumberField label="Quantidade de produtos completos" name="quantity" values={values} set={setQuantity}/><p className="info-box">Consumo total: {decimal(values.grams)} g. Ajuste os valores do lote conforme o fatiador. O estoque de cada filamento será baixado ao finalizar a produção.</p></>}
 {step===1&&!values.materials?.length&&<><p className="step-intro">Selecione uma variante do estoque ou informe o custo manualmente. Peso e tempo sempre se referem ao lote completo.</p><div className="form-grid"><Field label="Marca"><select value={brandChoice} onChange={e=>{const b=e.target.value;setBrandChoice(b);setColorChoice('');const matches=filament.filter(m=>m.brand===b);chooseMaterial(matches.length===1?matches[0]:null);}}><option value="">Todas as marcas</option>{brands.map(b=><option key={b}>{b}</option>)}</select></Field><Field label="Cor"><select value={colorChoice} onChange={e=>{const c=e.target.value;setColorChoice(c);const matches=filament.filter(m=>(!brandChoice||m.brand===brandChoice)&&m.color===c);chooseMaterial(matches.length===1?matches[0]:null);}}><option value="">Todas as cores</option>{colors.map(c=><option key={c}>{c}</option>)}</select></Field><Field label="Material / variante"><select value={values.materialId||''} onChange={e=>chooseMaterial(filament.find(m=>m.id===e.target.value))}><option value="">Informar manualmente</option>{variants.map(m=><option key={m.id} value={m.id}>{m.name} · {m.material_type} · {m.brand} · {m.color}</option>)}</select></Field><NumberField label="Preço do filamento (R$/kg)" name="kgPrice" values={values} set={setValues}/></div>{selectedMaterial&&<div className="material-preview"><MaterialPhoto material={selectedMaterial}/><div><Badge>{selectedMaterial.material_type||'Material'}</Badge><h3>{selectedMaterial.brand} · {selectedMaterial.color}</h3><p>{selectedMaterial.name}</p><small>Disponível: {decimal(selectedMaterial.quantity)} g · Custo médio: {selectedMaterial.cost_pending?'Pendente — informe o preço por kg para simular':money(Number(selectedMaterial.unit_cost)*1000)+'/kg'}</small>{Number(values.grams)>Number(selectedMaterial.quantity)&&<p className="negative">O consumo previsto excede o estoque atual.</p>}</div></div>}<div className="form-grid spaced"><NumberField label="Consumo total da mesa (g)" hint="Inclua suportes, purga e todas as peças." name="grams" values={values} set={setValues}/><NumberField label="Quantidade de peças no lote" name="quantity" values={values} set={setQuantity}/></div>{!filament.length&&<div className="info-box">Cadastre a marca, a cor e a foto em Estoque para selecionar seus filamentos aqui.</div>}</>}
 {step===2&&<><p className="step-intro">Use a estimativa do fatiador e o consumo médio da sua impressora.</p><div className="form-grid"><Field label="Impressora cadastrada"><select value={values.equipmentId||''} onChange={e=>{const m=data.equipment.find(m=>m.id===e.target.value);setValues({...values,equipmentId:m?.id||'',...(m?{watts:Number(m.watts),machineValue:Number(m.purchase_value),lifeHours:Number(m.life_hours)}:{})});}}>{options(data.equipment.filter(m=>m.kind==='impressora'),m=>m.name)}</select></Field>{values.plates?.length?<Field label="Tempo total das mesas"><input readOnly value={decimal(values.hours)+' h — ajuste na etapa Material'}/></Field>:<NumberField label="Tempo total de impressão (horas)" hint="Ex.: 1,5 = 1 hora e 30 minutos." name="hours" values={values} set={setValues}/>}<NumberField label="Potência média (W)" name="watts" values={values} set={setValues}/><NumberField label="Tarifa de energia (R$/kWh)" hint="Use o valor da sua conta de energia." name="kwh" values={values} set={setValues}/><NumberField label="Valor da impressora (R$)" name="machineValue" values={values} set={setValues}/><NumberField label="Vida útil estimada (horas)" name="lifeHours" values={values} set={setValues}/></div></>}
 {step===3&&<><p className="step-intro">Some o trabalho manual e os materiais auxiliares de todo o lote.</p><div className="form-grid"><NumberField label="Trabalho manual total (min)" hint="Preparação, acabamento e embalagem." name="laborMinutes" values={values} set={setValues}/><NumberField label="Sua hora de trabalho (R$)" name="hourRate" values={values} set={setValues}/><NumberField label="Extras do lote (R$)" hint="Embalagem, acessórios, desgaste e outros." name="extras" values={values} set={setValues}/><NumberField label="Reserva adicional para falhas (%)" hint="Reserva sobre o custo; não é a taxa real de falhas." name="failurePercent" values={values} set={setValues}/></div><div className="info-box">A compra de material movimenta o caixa. O custo da peça considera apenas a quantidade consumida.</div></>}
 {step===4&&<><p className="step-intro">Informe as taxas do seu canal de venda. Os percentuais são calculados sobre o preço final.</p><div className="form-grid"><NumberField label="Comissão de venda (%)" name="feePercent" values={values} set={setValues}/><NumberField label="Imposto sobre a venda (%)" name="taxPercent" values={values} set={setValues}/><NumberField label="Taxa fixa do lote (R$)" name="fixedFee" values={values} set={setValues}/><NumberField label="Acréscimo sobre o custo (%)" name="markupPercent" values={values} set={setValues}/></div><div className="info-box">Revise o resumo antes de salvar. Um desconto reduz o lucro; o sistema recalcula as taxas e a margem.</div></>}
 <div className="wizard-footer"><button className="secondary" disabled={step===0} onClick={()=>setStep(step-1)}>← Anterior</button><span>Etapa {step+1} de 5</span>{step<4?<button className="primary" onClick={()=>setStep(step+1)}>Próxima etapa →</button>:<button className="primary" disabled={busy||!connected||!projectName.trim()||!result} onClick={()=>saveQuote()}>{editingQuote?'Salvar alterações':'Salvar orçamento'}</button>}</div></section></div>
 <aside className="quote-sidebar"><section className="price-panel"><div className="print-heading"><h2>{projectName||'Resumo de precificação'}</h2><p>{customer}</p><p>{description}</p><p>{values.quantity} peça(s)</p></div><h2>Resumo do cálculo</h2><div className="price-and-discount"><div><p className="eyebrow">PREÇO FINAL UNITÁRIO</p><strong className="price">{result?money(result.unitPrice):'—'}</strong></div><Field label="Desconto"><div className="discount-control"><input aria-label="Valor do desconto" type="number" min="0" step="any" value={values.discountValue??0} onChange={e=>setValues({...values,discountValue:e.target.value})}/><select aria-label="Tipo de desconto" value={values.discountType||'percent'} onChange={e=>setValues({...values,discountType:e.target.value})}><option value="percent">%</option><option value="fixed">R$ / lote</option></select></div></Field></div><p>{result?money(result.price):'—'} pelo lote completo</p>{calculationError?<p role="alert" className="negative">{calculationError}</p>:<><div className="summary-metrics"><div><span>Lucro unitário</span><b className={result.unitProfit<0?'negative':''}>{money(result.unitProfit)}</b></div><div><span>Margem na venda</span><b>{decimal(result.margin)}%</b></div><div><span>Custo unitário</span><b>{money(result.unitCost)}</b></div><div><span>Recuperar máquina*</span><b>{result.roiPieces?decimal(result.roiPieces)+' peças':'—'}</b></div></div>{result.profit<0&&<p className="loss-warning">Este preço não cobre todos os custos e taxas.</p>}<button className="primary" disabled={busy||!connected||!projectName.trim()} onClick={()=>saveQuote()}>{busy?'Salvando…':editingQuote?'Salvar alterações':'Salvar orçamento'}</button><div className="summary-actions"><CustomerQuoteButton quote={{name:projectName,customer,description,result}} company={identity.company.name} disabled={!projectName.trim()||!result}/><button className="secondary" disabled={busy||!connected||!projectName.trim()} onClick={()=>saveQuote(true)}>Produção</button><button className="secondary" onClick={()=>setTab('stock')}>Estoque</button></div><button className="text-button" onClick={()=>setTab('sales')}>Vender um lote já produzido →</button><small>*Estimativa pelo lucro previsto por peça. Não considera prazo, despesas gerais ou vendas futuras.</small></>}</section>
 <section className="panel strategy"><div className="panel-heading"><h2>Estratégia de preço</h2><Badge>{decimal(values.markupPercent)}%</Badge></div><Field label="Acréscimo sobre o custo"><input type="range" min="0" max="300" step="1" value={Math.min(300,Number(values.markupPercent)||0)} onChange={e=>setValues({...values,markupPercent:e.target.value})}/></Field><div className="presets">{[['25%',25],['50%',50],['80%',80],['100%',100]].map(([label,n])=>{let r;try{r=calculate({...values,markupPercent:n,discountValue:0});}catch{}return <button key={label} className={Number(values.markupPercent)===n?'selected':''} onClick={()=>setValues({...values,markupPercent:n})}><span>{label}</span><b>{r?money(r.unitPrice):'—'}</b></button>;})}</div><p className="footnote">Simulações por peça, antes do desconto. Ajuste o percentual ao seu negócio.</p></section>
 {result&&<CostAnalysis result={result} input={values} projectName={projectName} material={selectedMaterial}/>}
 </aside></div>}
 {tab==='quotes'&&<section className="panel"><Table headers={['Projeto / cliente','Peças','Custo do lote','Preço do lote','Ações']} rows={data.quotes.map(q=>[<><b>{q.name}</b><small>{q.customer||'Sem cliente'}</small></>,q.result.quantity,money(q.result.totalCost),money(q.result.price),<div className="actions"><CustomerQuoteButton quote={q} company={identity.company.name}/><button className="secondary" onClick={()=>loadQuote(q)}>Abrir cópia</button>{canWrite&&<button className="secondary" disabled={busy||data.jobs.some(j=>j.quote_id===q.id)} title={data.jobs.some(j=>j.quote_id===q.id)?'Em produção: abra uma cópia para preservar o histórico':undefined} onClick={()=>loadQuote(q,true)}>Editar</button>}<button className="primary" onClick={()=>open('job','Produzir orçamento',{quoteId:q.id})}>Produzir</button>{canWrite&&<button className="secondary negative" disabled={busy||!connected||data.jobs.some(j=>j.quote_id===q.id)} title={data.jobs.some(j=>j.quote_id===q.id)?'Orçamento vinculado à produção':undefined} onClick={()=>open('deleteQuote','Excluir orçamento',{quoteId:q.id})}>Excluir</button>}</div>])}/></section>}
 {tab==='stock'&&<><div className="stock-toolbar"><Input label="Buscar material" value={stockSearch} onChange={e=>setStockSearch(e.target.value)} placeholder="Nome, marca, cor ou código"/><Field label="Marca"><select value={stockBrand} onChange={e=>setStockBrand(e.target.value)}><option value="">Todas</option>{[...new Set(data.materials.map(m=>m.brand).filter(Boolean))].map(b=><option key={b}>{b}</option>)}</select></Field><Field label="Material"><select value={stockType} onChange={e=>setStockType(e.target.value)}><option value="">Todos</option>{[...new Set(data.materials.map(m=>m.material_type).filter(Boolean))].map(b=><option key={b}>{b}</option>)}</select></Field></div><section className="panel"><div className="panel-heading"><div><h2>Materiais e insumos</h2><p className="footnote">{data.materials.length} variantes · {money(totals.stock)} em estoque{data.materials.some(m=>m.cost_pending)&&' · valor parcial: há custos pendentes'}</p></div><div className="actions"><button className="primary" disabled={!connected||!data.materials.length} onClick={()=>open('purchase','Registrar compra')}>＋ Compra</button><button className="secondary" disabled={!connected||!data.materials.length} onClick={()=>open('consume','Registrar saída de estoque')}>Saída / perda</button></div></div><div className="material-cards">{visibleMaterials.map(m=><article className="material-card" key={m.id}><MaterialPhoto material={m}/><div className="material-card-body"><div className="panel-heading"><Badge>{m.material_type||'Insumo'}</Badge><Badge tone={Number(m.quantity)<=Number(m.minimum)?'warn':'good'}>{Number(m.quantity)<=Number(m.minimum)?'Repor':'Disponível'}</Badge></div><h3>{m.name}</h3><p>{m.brand||'Marca não informada'} · {m.color||'Cor não informada'}</p><div className="stock-quantity">{decimal(m.quantity)} <small>{m.unit}</small></div><div className="list-row"><span>Custo médio / {m.unit==='g'?'kg':'un.'}</span><b>{m.cost_pending?'Pendente':money(Number(m.unit_cost)*(m.unit==='g'?1000:1))}</b></div><div className="list-row"><span>Estoque mínimo</span><b>{decimal(m.minimum)} {m.unit}</b></div><small className="stock-location">{m.sku&&'Código: '+m.sku}{m.location&&' · '+m.location}</small>{m.cost_pending&&<button className="primary" onClick={()=>open('openingCost','Informar custo inicial',{materialId:m.id})}>Informar custo</button>}<button className="secondary" onClick={()=>open('materialUpdate','Editar material',{materialId:m.id})}>Editar cadastro</button></div></article>)}</div>{!visibleMaterials.length&&<div className="empty"><strong>{data.materials.length?'Nenhum material corresponde aos filtros.':'Cadastre seu primeiro filamento.'}</strong><p>Organize por marca, tipo, cor e localização. Cada variante pode ter sua própria foto.</p></div>}</section><section className="panel"><h2>Histórico de movimentações</h2><Table headers={['Material','Motivo','Quantidade','Custo da movimentação','Data']} rows={data.movements.map(m=>{const material=data.materials.find(x=>x.id===m.material_id);return [material?.name,m.reason,decimal(m.quantity)+' '+(material?.unit||''),material?.cost_pending&&m.reason==='Saldo inicial'?'Pendente':money(Math.abs(Number(m.quantity))*Number(m.unit_cost)),new Date(m.created_at).toLocaleDateString('pt-BR')];})}/></section><p className="footnote">O estoque usa custo médio ponderado. A produção baixa o consumo confirmado, inclusive em falhas. Insumos em unidades podem ter saída manual e custo incluído nos extras do lote.</p></>}
 {tab==='maintenance'&&<Maintenance data={data} connected={connected} busy={busy} error={error} onSave={save} onAddEquipment={()=>open('equipment','Cadastrar impressora')}/>}
 {tab==='account'&&<Account identity={identity}/>}
 {tab==='equipment'&&<section className="panel"><Table headers={['Equipamento','Tipo','Valor de aquisição','Potência','Uso / vida útil']} rows={data.equipment.map(m=>[m.name,m.kind,money(m.purchase_value),decimal(m.watts)+' W',decimal(equipmentHours(m))+' / '+decimal(m.life_hours)+' h'])}/></section>}
 {tab==='production'&&<section className="panel"><Table headers={['Projeto','Unidades','Consumo previsto','Material','Estado','Custo real do lote','Ação']} rows={data.jobs.map(j=>[quoteOf(j.quote_id)?.name,quoteOf(j.quote_id)?.result.quantity,decimal(quoteOf(j.quote_id)?.input.grams)+' g',quoteOf(j.quote_id)?.input.materials?.map(m=>data.materials.find(x=>x.id===m.materialId)?.name||m.name).join(' + ')||data.materials.find(m=>m.id===j.material_id)?.name,<Badge tone={j.status==='falha'?'warn':j.status==='concluido'?'good':''}>{({fila:'Na fila',concluido:'Concluído',falha:'Falha'})[j.status]}</Badge>,j.status==='fila'?'—':money(j.actual_cost),j.status==='fila'?<button className="primary" onClick={()=>open('finish','Finalizar produção',{jobId:j.id})}>Finalizar</button>:j.status==='concluido'&&!data.sales.some(s=>s.job_id===j.id)?<button className="secondary" onClick={()=>open('sale','Registrar venda',{jobId:j.id})}>Vender lote</button>:'—'])}/></section>}
 {tab==='sales'&&<section className="panel"><Table headers={['Projeto','Venda','Taxas','Custo real','Resultado','Pagamento']} rows={data.sales.map(s=>[nameOfJob(s.job_id),money(s.amount),money(s.fees),money(s.cost),money(Number(s.amount)-Number(s.fees)-Number(s.cost)),s.paid_on?<Badge tone="good">Recebido</Badge>:<button className="primary" onClick={()=>open('receive','Confirmar recebimento',{saleId:s.id})}>Receber</button>])}/></section>}
 {tab==='finance'&&<><InvestmentPanel data={data} connected={connected} onEntry={kind=>open('entry','Novo lançamento',{kind})} onEquipment={()=>open('equipment','Cadastrar equipamento')} onStock={()=>setTab('stock')}/><div className="dashboard-grid"><section className="panel"><h2>Resultado no período</h2>{[['Vendas',totals.revenue],['Custos dos lotes vendidos',-totals.cost],['Taxas das vendas',-totals.fees],['Falhas de produção',-totals.loss],['Despesas adicionais',-totals.overhead],['Resultado gerencial',totals.profit]].map(([k,v])=><div className="list-row" key={k}><span>{k}</span><b>{money(v)}</b></div>)}</section><section className="panel"><h2>Patrimônio e caixa</h2><div className="list-row"><span>Estoque atual de materiais</span><b>{money(totals.stock)}{data.materials.some(m=>m.cost_pending)&&' (parcial; custos pendentes)'}</b></div><div className="list-row"><span>Equipamentos · aquisição</span><b>{money(totals.assets)}</b></div><div className="list-row"><span>Investimentos pagos no período</span><b>{money(totals.investment)}</b></div><p className="muted">Compras de material e equipamentos saem do caixa. No resultado, o material entra pelo consumo da peça vendida, e a máquina pela amortização.</p></section></div><section className="panel"><h2>Livro de caixa</h2><Table headers={['Data','Descrição','Categoria','Valor','Impacta resultado']} rows={totals.entries.map(e=>[String(e.occurred_on).slice(0,10).split('-').reverse().join('/'),e.description,e.kind,money(e.amount),e.affects_result?'Sim':'Via custos / somente caixa'])}/></section><p className="footnote">Despesas já incluídas na produção (como energia e trabalho) devem ser registradas apenas no caixa para não descontar o mesmo custo duas vezes. Relatório gerencial, com custos estimados onde não há medição real.</p></>}
 {loading&&<p role="status" className="footnote">Atualizando registros…</p>}
 </div></main>
 {modal&&<div className="modal-backdrop"><section ref={dialogRef} className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="panel-heading"><h2 id="modal-title">{modal.title}</h2><button className="close" disabled={busy} onClick={()=>setModal(null)} aria-label="Fechar">×</button></div><form key={modal.draft?.id||modal.payload.materialId||modal.action} onSubmit={submit}><div className="form-grid">
 {modal.action==='deleteQuote'&&<p>Excluir o orçamento <strong>{quoteOf(modal.payload.quoteId)?.name}</strong>? Esta ação não pode ser desfeita.</p>}
 {['material','materialUpdate'].includes(modal.action)&&<><Field label="Preencher com foto do catálogo"><select defaultValue={modal.draft?.id||''} onChange={e=>{const model=filamentCatalog.find(c=>c.id===e.target.value);if(model)setModal({...modal,draft:{...materialDefaults,...model,sku:materialDefaults?.sku||'',location:materialDefaults?.location||'',supplier:materialDefaults?.supplier||''}});}}><option value="">Cadastro manual / foto própria</option>{['Masterprint','Bambu Lab','Voolt3D','Aura','Sunlu','eSun'].map(b=><optgroup label={b} key={b}>{filamentCatalog.filter(c=>c.brand===b).map(c=><option key={c.id} value={c.id}>{c.material_type} · {c.color}</option>)}</optgroup>)}</select></Field>{materialDefaults?.image_url&&<div className="catalog-preview"><MaterialPhoto material={materialDefaults}/>{materialDefaults.source_url&&<a href={materialDefaults.source_url} target="_blank" rel="noreferrer">Ver origem da foto ↗</a>}</div>}<Input name="name" label="Nome da variante" defaultValue={materialDefaults?.name} required autoFocus placeholder="Ex.: PLA Basic Preto"/><Field label="Unidade"><select name="unit" defaultValue={materialDefaults?.unit||'g'}><option value="g">Gramas (filamento / resina)</option><option value="un">Unidades (insumos)</option></select></Field><Field label="Marca"><input name="brand" list="filament-brands" defaultValue={materialDefaults?.brand} placeholder="Selecione ou digite"/><datalist id="filament-brands">{['Masterprint','Bambu Lab','Voolt3D','Aura','Sunlu','eSun'].map(b=><option key={b} value={b}/>)}</datalist></Field><Field label="Tipo / linha"><input name="materialType" list="material-types" defaultValue={materialDefaults?.material_type||'PLA'} required/><datalist id="material-types">{['PLA','PLA Basic','PLA Matte','PLA Silk','PLA+','PETG','ABS','ASA','TPU','Resina','Insumo'].map(t=><option key={t} value={t}/>)}</datalist></Field><Input name="color" label="Nome da cor" defaultValue={materialDefaults?.color} placeholder="Ex.: Preto / Black 10101"/><Input name="colorHex" label="Cor de referência" type="color" defaultValue={materialDefaults?.color_hex||'#808080'}/><Input name="sku" label="Código / SKU (opcional)" defaultValue={materialDefaults?.sku}/><Input name="minimum" label="Estoque mínimo na unidade cadastrada" type="number" defaultValue={materialDefaults?.minimum||'100'} required/><Input name="location" label="Localização" defaultValue={materialDefaults?.location} placeholder="Ex.: Prateleira A / caixa 2"/><Input name="supplier" label="Fornecedor" defaultValue={materialDefaults?.supplier}/><Input name="imageUrl" label="Link da foto (opcional)" defaultValue={materialDefaults?.image_url} placeholder="https://..."/><Field label="Ou envie uma foto (até 5 MB)"><input name="imageFile" type="file" accept="image/png,image/jpeg,image/webp"/></Field><Field label="Observações"><textarea name="notes" defaultValue={materialDefaults?.notes} rows="3" placeholder="Lote do fabricante, conservação e detalhes"/></Field><p className="form-note">A foto desta variante será exibida ao selecionar marca e cor no orçamento. Cadastre o saldo pela opção Compra, mantendo o histórico de estoque e pagamentos.</p></>}
 {modal.action==='openingCost'&&<><p className="form-note">{materialDefaults?.name} · {decimal(materialDefaults?.quantity)} {materialDefaults?.unit}. Informe o custo total desse saldo. Isso atualiza a valorização do estoque, sem lançar pagamento no caixa.</p><Input name="total" label="Custo total do saldo inicial (R$)" type="number" min="0.01" step="0.01" required autoFocus/></>}
 {modal.action==='purchase'&&<><Field label="Material"><select name="materialId" required autoFocus>{options(data.materials,m=>m.name+' ('+m.unit+')')}</select></Field><Input name="quantity" label="Quantidade na unidade cadastrada" type="number" min="0.0001" required/><Input name="total" label="Total pago (R$), incluindo frete" type="number" min="0.01" step="0.01" required/><p className="form-note">A compra aumenta o estoque e registra a saída no caixa.</p></>}
 {modal.action==='consume'&&<><Field label="Material"><select name="materialId" required>{options(data.materials,m=>m.name+' ('+m.unit+')')}</select></Field><Input name="quantity" label="Quantidade utilizada / perdida" type="number" min="0.0001" required/><Field label="Motivo"><select name="reason"><option>Consumo de insumo</option><option>Perda avulsa</option></select></Field><p className="form-note">Consumo de insumo: inclua o custo nos extras da produção. Perda avulsa: o custo será descontado do resultado. Nenhuma das opções cria um novo pagamento.</p></>}
 {modal.action==='equipment'&&<><Input name="name" label="Nome / modelo" required autoFocus/><Field label="Tipo"><select name="kind"><option value="impressora">Impressora</option><option value="ferramenta">Ferramenta</option></select></Field><Input name="purchaseValue" label="Valor de aquisição (R$)" type="number" required/><Input name="watts" label="Potência média (W)" type="number" defaultValue="200" required/><Input name="lifeHours" label="Vida útil (horas)" type="number" defaultValue="10000" min="1" required/><label className="check"><input name="recordPayment" type="checkbox"/> Registrar pagamento no caixa agora</label></>}
 {modal.action==='job'&&<>{!modal.payload.quoteId&&<Field label="Orçamento"><select name="quoteId" required defaultValue="" onChange={e=>setModal({...modal,payload:{...modal.payload,quoteId:e.target.value}})}>{options(data.quotes,q=>q.name)}</select></Field>}{quoteOf(modal.payload.quoteId)?.input.materials?.length?<><input type="hidden" name="materialId" value={quoteOf(modal.payload.quoteId).input.materials[0].materialId}/><p className="info-box">{quoteOf(modal.payload.quoteId).result.quantity} unidade(s) · {quoteOf(modal.payload.quoteId).input.materials.map(m=>(m.name||data.materials.find(x=>x.id===m.materialId)?.name)+': '+decimal(m.grams)+' g').join(' · ')}</p></>:<Field label="Filamento / resina"><select name="materialId" required autoFocus defaultValue={quoteOf(modal.payload.quoteId)?.input.materialId||values.materialId||''}>{options(data.materials.filter(m=>m.unit==='g'),m=>m.name+' · '+decimal(m.quantity)+' g')}</select></Field>}<Field label="Equipamento (opcional)"><select name="equipmentId" defaultValue={quoteOf(modal.payload.quoteId)?.input.equipmentId||values.equipmentId||''}>{options(data.equipment.filter(e=>e.kind==='impressora'),e=>e.name)}</select></Field><p className="form-note">A quantidade vem do orçamento. O consumo de cada filamento será confirmado ao finalizar.</p></>}
 {modal.action==='finish'&&<><p className="info-box">Lote de {productionQuote?.result.quantity} unidade(s) completas. Confira o consumo real antes de confirmar.</p>{productionQuote?.input.plates?.length>0&&<details><summary>Ver mesas planejadas</summary>{productionQuote.input.plates.map((p,i)=><p key={i}><b>{p.name}</b> · {decimal(p.hours)} h<br/>{p.materials.map(m=>(m.name||'Filamento')+': '+decimal(m.grams)+' g').join(' · ')}</p>)}</details>}<Field label="Resultado"><select name="status"><option value="concluido">Lote concluído</option><option value="falha">Falha / lote perdido</option></select></Field>{productionQuote?.input.materials?.length?productionQuote.input.materials.map(m=><Input key={m.materialId} name={'grams_'+m.materialId} defaultValue={m.grams} label={'Consumo real (g): '+(m.name||data.materials.find(x=>x.id===m.materialId)?.name)} type="number" required/>):<Input name="grams" defaultValue={productionQuote?.input.grams} label="Material realmente consumido (g)" type="number" required autoFocus/>}<Input name="hours" defaultValue={productionQuote?.input.hours} label="Tempo real de impressão (h)" type="number" required/><Input name="laborMinutes" defaultValue={productionQuote?.input.laborMinutes} label="Trabalho manual real (min)" type="number" required/><Input name="extras" label="Custos adicionais reais (R$)" type="number" defaultValue={productionQuote?.input.extras||0} required/><p className="form-note">O material será baixado do estoque. Energia, hora de trabalho e amortização usam as tarifas do orçamento e o equipamento selecionado.</p></>}
 {modal.action==='sale'&&<>{!modal.payload.jobId&&<Field label="Lote concluído"><select name="jobId" required autoFocus>{options(availableJobs,j=>quoteOf(j.quote_id)?.name)}</select></Field>}<Input name="amount" label="Valor total da venda (R$)" type="number" min="0.01" step="0.01" required/><Input name="fees" label="Total de taxas e impostos (R$)" type="number" defaultValue="0" step="0.01" required/><label className="check"><input name="paid" type="checkbox" defaultChecked/> Já recebi o pagamento integral</label><p className="form-note">A venda considera todas as peças deste lote. Informe o total após descontos.</p></>}
 {modal.action==='entry'&&<><Input name="description" label="Descrição" required autoFocus/><Field label="Categoria"><select name="kind" defaultValue={modal.payload?.kind||'despesa'}><option value="despesa">Despesa</option><option value="investimento">Investimento</option><option value="aporte">Aporte do proprietário</option><option value="retirada">Retirada do proprietário</option></select></Field><Input name="amount" label="Valor pago / recebido (R$)" type="number" step="0.01" min="0.01" required/><label className="check"><input name="affectsResult" type="checkbox"/> Descontar também do resultado (apenas despesas que não estão nos custos de produção)</label></>}
 {!['material','materialUpdate','job','quote','openingCost','deleteQuote'].includes(modal.action)&&<Input name="date" label={modal.action==='receive'?'Data do recebimento':'Data'} type="date" defaultValue={today()} required/>}
 </div>{error&&<p role="alert" className="negative">{error}</p>}<div className="modal-footer"><button className="secondary" type="button" disabled={busy} onClick={()=>setModal(null)}>Cancelar</button><button className="primary" disabled={busy}>{busy?(modal.action==='deleteQuote'?'Excluindo…':'Salvando…'):(modal.action==='deleteQuote'?'Excluir orçamento':'Confirmar registro')}</button></div></form></section></div>}
 </div>;
}
